{
  "name": "invoices",
  "$schema": "../../node_modules/nx/schemas/project-schema.json",
  "projectType": "application",
  "prefix": "app",
  "sourceRoot": "apps/invoices/src",
  "tags": [],
  "targets": {
    "build": {
      "executor": "@angular-devkit/build-angular:application",
      "outputs": ["{options.outputPath}"],
      "options": {
        "outputPath": "dist/apps/invoices",
        "index": "apps/invoices/src/index.html",
        "browser": "apps/invoices/src/main.ts",
        "polyfills": ["zone.js"],
        "tsConfig": "apps/invoices/tsconfig.app.json",
        "inlineStyleLanguage": "scss",
        "assets": [
          {
            "glob": "**/*",
            "input": "apps/invoices/public"
          },
          {
            "input": "libs/shared",
            "glob": "*/*/assets/translations/*",
            "output": "assets/shared"
          },
          {
            "glob": "**/*.json",
            "input": "apps/invoices/assets/translations",
            "output": "assets/translations"
          }
        ],
        "styles": ["apps/invoices/src/styles.scss"],
        "scripts": []
      },
      "configurations": {
        "production": {
          "budgets": [
            {
              "type": "initial",
              "maximumWarning": "1mb",
              "maximumError": "2mb"
            },
            {
              "type": "anyComponentStyle",
              "maximumWarning": "8kb",
              "maximumError": "16kb"
            }
          ],
          "fileReplacements": [
            {
              "replace": "libs/shared/environments/src/lib/environment.ts",
              "with": "libs/shared/environments/src/lib/environment.prod.ts"
            }
          ],
          "outputHashing": "all"
        },
        "staging": {
          "budgets": [
            {
              "type": "initial",
              "maximumWarning": "1mb",
              "maximumError": "2mb"
            },
            {
              "type": "anyComponentStyle",
              "maximumWarning": "8kb",
              "maximumError": "16kb"
            }
          ],
          "fileReplacements": [
            {
              "replace": "libs/shared/environments/src/lib/environment.ts",
              "with": "libs/shared/environments/src/lib/environment.staging.ts"
            }
          ],
          "outputHashing": "all"
        },
        "development-staging": {
          "sourceMap": true,
          "fileReplacements": [
            {
              "replace": "libs/shared/environments/src/lib/environment.ts",
              "with": "libs/shared/environments/src/lib/environment.dev-staging.ts"
            }
          ],
          "preserveSymlinks": true
        },
        "development": {
          "optimization": false,
          "extractLicenses": false,
          "sourceMap": true
        }
      },
      "defaultConfiguration": "production"
    },
    "serve": {
      "executor": "@angular-devkit/build-angular:dev-server",
      "options": {
        "host": "financial-hq-invoices.ui.sportngin.com.dev",
        "port": 39323,
        "publicHost": "https://financial-hq-invoices.ui.sportngin.com.dev"
      },
      "configurations": {
        "production": {
          "buildTarget": "invoices:build:production"
        },
        "staging": {
          "buildTarget": "invoices:build:production,staging"
        },
        "development-staging": {
          "buildTarget": "invoices:build:development,development-staging"
        },
        "development": {
          "buildTarget": "invoices:build:development"
        }
      },
      "defaultConfiguration": "development",
      "continuous": true
    },
    "extract-i18n": {
      "executor": "@angular-devkit/build-angular:extract-i18n",
      "options": {
        "buildTarget": "invoices:build"
      }
    },
    "lint": {
      "executor": "@nx/eslint:lint"
    },
    "test": {
      "executor": "@nx/jest:jest",
      "outputs": ["{workspaceRoot}/coverage/{projectRoot}"],
      "options": {
        "jestConfig": "apps/invoices/jest.config.ts",
        "tsConfig": "apps/invoices/tsconfig.spec.json"
      }
    },
    "serve-static": {
      "executor": "@nx/web:file-server",
      "options": {
        "buildTarget": "invoices:build",
        "staticFilePath": "dist/apps/invoices",
        "spa": true
      }
    },
    "deploy": {
      "executor": "nx:run-commands",
      "configurations": {
        "production": {
          "parallel": false,
          "commands": [
            "./scripts/deploy-static-site.sh dist/apps/invoices financial-hq-invoices.ui.sportsengine.com financial-hq-invoices.ui.sportsengine.com"
          ]
        },
        "staging": {
          "parallel": false,
          "commands": [
            "./scripts/deploy-static-site.sh dist/apps/invoices financial-hq-invoices.ui.sestage.us financial-hq-invoices.ui.stage.ngin-staging.com"
          ]
        }
      },
      "defaultConfiguration": "production"
    }
  }
}

